-- Read-only inventory. Future remote use requires separate authorization.
-- No business rows or Auth identities are exported. SQL definitions/role settings
-- may contain sensitive metadata: keep remote output private, never commit it.
SELECT jsonb_build_object(
  'format', 'procont-recovery-v1',
  'database_oid', (SELECT oid FROM pg_database WHERE datname=current_database()),
  'server_version_num', current_setting('server_version_num'),
  'operator', current_user,
  'schemas', (SELECT coalesce(jsonb_object_agg(n.nspname, jsonb_build_object('oid',n.oid,'owner',pg_get_userbyid(n.nspowner),'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(g.grantor),'grantee',CASE WHEN g.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(g.grantee) END,'privilege',g.privilege_type,'grantable',g.is_grantable) ORDER BY g.grantor,g.grantee,g.privilege_type),'[]'::jsonb) FROM aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) g))), '{}'::jsonb) FROM pg_namespace n WHERE n.nspname !~ '^pg_' AND n.nspname <> 'information_schema'),
  'relations', (SELECT coalesce(jsonb_object_agg(format('%I.%I',n.nspname,c.relname), jsonb_build_object('oid',c.oid,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(g.grantor),'grantee',CASE WHEN g.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(g.grantee) END,'privilege',g.privilege_type,'grantable',g.is_grantable) ORDER BY g.grantor,g.grantee,g.privilege_type),'[]'::jsonb) FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) g),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'replident',c.relreplident,'options',to_jsonb(c.reloptions),'view',CASE WHEN c.relkind IN ('v','m') THEN pg_get_viewdef(c.oid,true) END)), '{}'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname !~ '^pg_' AND n.nspname <> 'information_schema' AND c.relkind IN ('r','p','v','m','S','f')),
  'columns', (SELECT coalesce(jsonb_object_agg(format('%I.%I.%I',n.nspname,c.relname,a.attname), jsonb_build_object('number',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(g.grantor),'grantee',CASE WHEN g.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(g.grantee) END,'privilege',g.privilege_type,'grantable',g.is_grantable) ORDER BY g.grantor,g.grantee,g.privilege_type),'[]'::jsonb) FROM aclexplode(a.attacl) g),'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated)), '{}'::jsonb) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname !~ '^pg_' AND n.nspname <> 'information_schema' AND a.attnum>0 AND NOT a.attisdropped AND c.relkind IN ('r','p','v','m','f')),
  -- NOT NULL is recorded in columns; PG18 additionally exposes it in pg_constraint.
  'constraints', (SELECT coalesce(jsonb_object_agg(format('%I.%I.%I',n.nspname,c.relname,x.conname), jsonb_build_object('oid',x.oid,'definition',pg_get_constraintdef(x.oid,true),'validated',x.convalidated)), '{}'::jsonb) FROM pg_constraint x JOIN pg_class c ON c.oid=x.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname !~ '^pg_' AND n.nspname <> 'information_schema' AND x.contype <> 'n'),
  'indexes', (SELECT coalesce(jsonb_object_agg(format('%I.%I',n.nspname,c.relname), jsonb_build_object('oid',c.oid,'owner',pg_get_userbyid(c.relowner),'definition',pg_get_indexdef(c.oid),'valid',i.indisvalid)), '{}'::jsonb) FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname !~ '^pg_' AND n.nspname <> 'information_schema'),
  'functions', (SELECT coalesce(jsonb_object_agg(format('%I.%I(%s)',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)), jsonb_build_object('oid',p.oid,'owner',pg_get_userbyid(p.proowner),'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(g.grantor),'grantee',CASE WHEN g.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(g.grantee) END,'privilege',g.privilege_type,'grantable',g.is_grantable) ORDER BY g.grantor,g.grantee,g.privilege_type),'[]'::jsonb) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) g),'definition',pg_get_functiondef(p.oid))), '{}'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname !~ '^pg_' AND n.nspname <> 'information_schema' AND p.prokind IN ('f','p')),
  'triggers', (SELECT coalesce(jsonb_object_agg(format('%I.%I.%I',n.nspname,c.relname,t.tgname), jsonb_build_object('oid',t.oid,'definition',pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled)), '{}'::jsonb) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname !~ '^pg_' AND n.nspname <> 'information_schema' AND NOT t.tgisinternal),
  'policies', (SELECT coalesce(jsonb_object_agg(format('%I.%I.%I',n.nspname,c.relname,p.polname), jsonb_build_object('oid',p.oid,'command',p.polcmd,'permissive',p.polpermissive,'roles',to_jsonb(p.polroles),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid))), '{}'::jsonb) FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname !~ '^pg_' AND n.nspname <> 'information_schema'),
  'publications', (SELECT coalesce(jsonb_object_agg(p.pubname, jsonb_build_object('oid',p.oid,'owner',pg_get_userbyid(p.pubowner),'all',p.puballtables,'insert',p.pubinsert,'update',p.pubupdate,'delete',p.pubdelete,'truncate',p.pubtruncate,'via_root',p.pubviaroot)), '{}'::jsonb) FROM pg_publication p WHERE true),
  'publication_tables', (SELECT coalesce(jsonb_object_agg(format('%I.%I.%I',p.pubname,p.schemaname,p.tablename), jsonb_build_object('columns',to_jsonb(p.attnames),'filter',p.rowfilter)), '{}'::jsonb) FROM pg_publication_tables p WHERE true),
  'extensions', (SELECT coalesce(jsonb_object_agg(e.extname, jsonb_build_object('oid',e.oid,'schema',n.nspname,'owner',pg_get_userbyid(e.extowner),'version',e.extversion)), '{}'::jsonb) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE true),
  'default_acl', (SELECT coalesce(jsonb_object_agg(d.oid::text, to_jsonb(d)), '{}'::jsonb) FROM pg_default_acl d WHERE true),
  'roles', (SELECT coalesce(jsonb_object_agg(r.rolname, to_jsonb(r)-'rolpassword'-'rolvaliduntil'), '{}'::jsonb) FROM pg_roles r WHERE true),
  'role_members', (SELECT coalesce(jsonb_object_agg(format('%s:%s:%s',m.roleid,m.member,m.grantor), to_jsonb(m)), '{}'::jsonb) FROM pg_auth_members m WHERE true),
  'event_triggers', (SELECT coalesce(jsonb_object_agg(e.evtname, to_jsonb(e)), '{}'::jsonb) FROM pg_event_trigger e WHERE true),
  'rules', (SELECT coalesce(jsonb_object_agg(format('%I.%I.%I',n.nspname,c.relname,r.rulename),
    jsonb_build_object('oid',r.oid,'definition',pg_get_ruledef(r.oid,true),'enabled',r.ev_enabled)), '{}'::jsonb)
    FROM pg_rewrite r JOIN pg_class c ON c.oid=r.ev_class JOIN pg_namespace n ON n.oid=c.relnamespace
    WHERE n.nspname !~ '^pg_' AND n.nspname <> 'information_schema'),
  'types', (SELECT coalesce(jsonb_object_agg(format('%I.%I',n.nspname,t.typname),
    jsonb_build_object('oid',t.oid,'kind',t.typtype,'owner',pg_get_userbyid(t.typowner),'relation',t.typrelid,'acl',to_jsonb(t.typacl))), '{}'::jsonb)
    FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname !~ '^pg_' AND n.nspname <> 'information_schema'),
  'publication_schemas', (SELECT coalesce(jsonb_object_agg(p.oid::text,to_jsonb(p)), '{}'::jsonb) FROM pg_publication_namespace p),
  'row_counts', (SELECT coalesce(jsonb_object_agg(format('%I.%I',n.nspname,c.relname),
    ((xpath('/row/n/text()',query_to_xml(format('SELECT count(*) AS n FROM %I.%I',n.nspname,c.relname),false,true,'')))[1]::text)::bigint), '{}'::jsonb)
    FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND
      ((n.nspname='public' AND c.relname=ANY(ARRAY['users','requests','projects','project_flows','checklist_templates','checklist_items','comments','activity_logs','notifications']))
       OR n.nspname='app_private' OR (n.nspname='auth' AND c.relname='users'))),
  'templates_checksum', CASE WHEN to_regclass('public.checklist_templates') IS NOT NULL THEN
    md5(query_to_xml('SELECT * FROM public.checklist_templates ORDER BY id',false,true,'')::text) END,
  'history', CASE WHEN to_regclass('supabase_migrations.schema_migrations') IS NOT NULL THEN
    query_to_xml('SELECT version,name,md5(statements::text) AS statements_checksum FROM supabase_migrations.schema_migrations ORDER BY version',false,true,'')::text END
);
